-- 4) a importação (interna; devolve o resumo) ------------------------------------------------------------------------
create or replace function public.casting_groscove_2027_import(p_admin_email text default 'agencia@gmail.com')
returns jsonb language plpgsql set search_path = '' as $$
declare
  v_agency uuid; v_admin uuid; r jsonb; v_email text; v_handle text; v_tid uuid; v_user uuid; v_kinds text[]; v_acc jsonb;
  v_seg uuid; v_segs jsonb := '{}'::jsonb; v_topics text[]; v_notes text;
  n_created int := 0; n_existing int := 0; n_invited int := 0; n_linked int := 0; v_skipped jsonb := '[]'::jsonb;
begin
  select m.agency_id, m.user_id into v_agency, v_admin
  from public.agency_members m
  join auth.users u on u.id = m.user_id
  join public.agencies a on a.id = m.agency_id
  where lower(u.email::text) = lower(btrim(p_admin_email)) and m.role = 'admin' and m.revoked_at is null and a.status = 'active'
    and not public.agency_is_demo(a.id)
  order by a.created_at limit 1;
  if v_agency is null then
    return jsonb_build_object('agency', null, 'note', 'agência não encontrada: nada a importar');
  end if;

  -- segmentos (cria os que faltam; nomes editáveis depois pela agência)
  insert into public.talent_segments (agency_id, slug, name, sort_order) values
    (v_agency, 'musica', 'Música', 110), (v_agency, 'influencia', 'Influência', 120), (v_agency, 'esportes', 'Esporte', 30),
    (v_agency, 'atuacao', 'Atuação', 130), (v_agency, 'apresentacao', 'Apresentação', 140), (v_agency, 'humor', 'Humor', 150),
    (v_agency, 'moda-modelo', 'Moda/Modelo', 160), (v_agency, 'fotografia', 'Fotografia', 170),
    (v_agency, 'imprensa-digital', 'Imprensa digital', 180), (v_agency, 'negocios', 'Negócios', 190)
  on conflict (agency_id, slug) do nothing;
  select coalesce(jsonb_object_agg(s.slug, s.id), '{}'::jsonb) into v_segs from public.talent_segments s where s.agency_id = v_agency;

  for r in select x from jsonb_array_elements(public.casting_groscove_2027_data()) x loop
    v_email := lower(btrim(r ->> 'email'));
    v_handle := r ->> 'handle';
    select coalesce(array_agg(btrim(x)), '{}'::text[]) into v_topics from jsonb_array_elements_text(coalesce(r -> 'topics', '[]'::jsonb)) x;

    -- já está no casting da agência (mesmo e-mail de contato ou mesmo @): só completa o que está vazio
    select t.id into v_tid from public.talent_profiles t
    where t.agency_id = v_agency and t.archived_at is null
      and (exists (select 1 from public.access_contacts c where c.talent_id = t.id and c.email = v_email)
           or exists (select 1 from public.talent_social_accounts a where a.talent_id = t.id and a.network = 'instagram' and lower(a.handle) = lower(v_handle)))
    order by t.created_at limit 1;
    if v_tid is not null then
      update public.talent_profiles set
        photo_url = coalesce(photo_url, r ->> 'photo'),
        category_label = coalesce(category_label, r ->> 'category'),
        topics = case when cardinality(topics) = 0 then v_topics else topics end
      where id = v_tid and (photo_url is null or category_label is null or cardinality(topics) = 0);
      n_existing := n_existing + 1;
      continue;
    end if;

    begin
      -- um Hero por e-mail (0112) e um e-mail, um perfil (0116): pula com o motivo, sem gravar nada
      perform pg_advisory_xact_lock(hashtext('access_email:' || v_email));
      if exists (select 1 from public.access_contacts c join public.talent_profiles t on t.id = c.talent_id
                 where c.email = v_email and t.archived_at is null) then
        raise exception 'hero_email_taken' using errcode = 'P0001';
      end if;
      select u.id into v_user from auth.users u where lower(u.email::text) = v_email limit 1;
      if v_user is not null then
        v_kinds := public.account_business_kinds(v_user);
        if exists (select 1 from unnest(v_kinds) k where k <> 'hero')
           and not exists (select 1 from public.role_assignments ra where ra.user_id = v_user and ra.role::text = 'admin' and ra.revoked_at is null) then
          raise exception 'profile_conflict:%', (select k from unnest(v_kinds) k where k <> 'hero' limit 1) using errcode = 'P0001';
        end if;
      end if;

      v_notes := 'Importado do Casting Groscove 2027 (p. ' || (r ->> 'page') || ', ' || (r ->> 'section') || '). '
        || 'Celular a confirmar (provisório ' || (r ->> 'phone') || '). E-mail provável, gerado pelo padrão nome + inicial do sobrenome: confirmar.'
        || case when nullif(r ->> 'legal_name', '') is not null then ' Nome civil: ' || (r ->> 'legal_name') || '.' else '' end;
      insert into public.talent_profiles (agency_id, display_name, country, commercial_status, availability, internal_notes,
                                          photo_url, category_label, topics, is_demo, created_by)
      values (v_agency, btrim(r ->> 'name'), 'BR', 'prospect', 'available', v_notes,
              r ->> 'photo', r ->> 'category', v_topics, false, v_admin)
      returning id into v_tid;

      v_seg := (v_segs ->> (r ->> 'segment'))::uuid;
      if v_seg is not null then
        insert into public.talent_segment_links (agency_id, talent_id, segment_id) values (v_agency, v_tid, v_seg)
        on conflict (talent_id, segment_id) do nothing;
      end if;

      insert into public.talent_social_accounts (agency_id, talent_id, network, handle, url, followers, source, as_of, declared_by, declared_side)
      values (v_agency, v_tid, 'instagram', v_handle, r ->> 'url', (r ->> 'followers')::int, 'declared', current_date, v_admin, 'agency')
      on conflict (talent_id, network, handle) do nothing;

      insert into public.access_contacts (talent_id, email, phone_e164, created_by, updated_by)
      values (v_tid, v_email, r ->> 'phone', v_admin, v_admin);

      v_acc := public.access_provision('talent', v_tid, v_agency, v_email);
      n_created := n_created + 1;
      if v_acc ->> 'account' = 'invited' then n_invited := n_invited + 1;
      elsif v_acc ->> 'account' = 'linked' then n_linked := n_linked + 1; end if;
    exception when others then
      v_skipped := v_skipped || jsonb_build_array(jsonb_build_object('name', r ->> 'name', 'email', v_email, 'reason', sqlerrm));
    end;
  end loop;

  perform public.audit_log('casting.import', 'agency', v_agency::text, null,
    jsonb_build_object('source', 'Casting Groscove 2027', 'created', n_created, 'existing', n_existing, 'invited', n_invited,
                       'linked', n_linked, 'skipped', v_skipped), null, 'system');
  return jsonb_build_object('agency', v_agency, 'created', n_created, 'existing', n_existing, 'invited', n_invited,
                            'linked', n_linked, 'skipped', v_skipped);
end $$;
revoke execute on function public.casting_groscove_2027_import(text) from public, anon, authenticated;
grant execute on function public.casting_groscove_2027_import(text) to service_role;

-- 5) roda a importação (sem a agência, não faz nada) ------------------------------------------------------------------
do $$
declare v jsonb;
begin
  v := public.casting_groscove_2027_import('agencia@gmail.com');
  raise notice 'casting_groscove_2027_import: %', v;
end $$;

notify pgrst, 'reload schema';
